import { useState } from 'react'
import { useParams } from 'react-router-dom'
import { useQuery } from '@tanstack/react-query'
import { useTranslation } from 'react-i18next'
import { clsx } from 'clsx'
import { PageHeader } from '@/features/shell/PageHeader'
import { objectivesService } from '@/integrations/supabase/objectives'
import type { ObjectiveTab } from '@/entities/objective/types'
import { AboutTab } from './tabs/AboutTab'
import { AssignTab } from './tabs/AssignTab'
import { DeliverTab } from './tabs/DeliverTab'
import { EvaluateTab } from './tabs/EvaluateTab'
import { CompleteTab } from './tabs/CompleteTab'

const TABS: { id: ObjectiveTab; label: string }[] = [
  { id: 'about', label: 'About' },
  { id: 'assign', label: 'Assign' },
  { id: 'deliver', label: 'Deliver' },
  { id: 'evaluate', label: 'Evaluate' },
  { id: 'complete', label: 'Complete' },
]

export function ObjectiveWorkspacePage() {
  const { t } = useTranslation('objectives')
  const { objectiveId } = useParams()
  const [activeTab, setActiveTab] = useState<ObjectiveTab>('about')

  const { data: objective, isLoading } = useQuery({
    queryKey: ['objective', objectiveId],
    queryFn: () => objectivesService.getObjective(objectiveId ?? ''),
    enabled: !!objectiveId,
  })

  if (isLoading) return <div className="p-6 text-sm text-muted-foreground">Loading…</div>
  if (!objective) return <div className="p-6 text-sm text-muted-foreground">Objective not found.</div>

  return (
    <div className="flex flex-col h-full overflow-hidden">
      <PageHeader title={objective.title} subtitle={`Status: ${objective.status}`} />
      <div className="flex border-b border-border bg-surface shrink-0 overflow-x-auto">
        {TABS.map((tab, i) => (
          <button key={tab.id} onClick={() => setActiveTab(tab.id)}
            className={clsx('flex items-center gap-2 px-5 py-3 text-sm whitespace-nowrap border-b-2 transition-colors',
              activeTab === tab.id ? 'border-accent text-accent font-medium' : 'border-transparent text-muted-foreground hover:text-foreground')}>
            <span className="w-5 h-5 rounded-full text-xs flex items-center justify-center bg-muted font-medium">{i + 1}</span>
            {t(tab.id)}
          </button>
        ))}
      </div>
      <div className="flex-1 overflow-y-auto">
        {activeTab === 'about' && <AboutTab objective={objective} />}
        {activeTab === 'assign' && <AssignTab objective={objective} />}
        {activeTab === 'deliver' && <DeliverTab objective={objective} />}
        {activeTab === 'evaluate' && <EvaluateTab objective={objective} />}
        {activeTab === 'complete' && <CompleteTab objective={objective} onTabChange={setActiveTab} />}
      </div>
    </div>
  )
}
